#![allow(unused)]
use verus::prelude::*;

verus! {

    /// Returns the maximum element of a non‐empty vector of i8.
    ///
    /// # Requirements
    /// * `a.len() > 0`
    ///
    /// # Guarantees
    /// * The result is ≥ every element of `a`.
    /// * The result is equal to one of the elements of `a`.
    pub fn max(a: Vec<i8>) -> (result: i8)
      requires
        a.len() > 0,
      ensures
        // result is ≥ every element in a
        forall j: nat :: j < a.len() ==> result >= a[j],
      ensures
        // result is one of the elements in a
        exists k: nat :: k < a.len() && result == a[k]
    {
        // Initialize m to the first element
        let mut m = a[0];
        // We will scan from index 1 up to a.len()
        let mut i: usize = 1;

        // Loop until we've processed all entries
        while i < a.len()
            invariant
                // i never exceeds a.len()
                i <= a.len(),
            invariant
                // m is at least as large as every a[j] for j < i
                forall j: nat :: j < i ==> m >= a[j],
            invariant
                // m equals one of the elements a[k] with k < i
                exists k: nat :: k < i && m == a[k],
            decreases
                // each iteration processes one more element
                a.len() - i
        {
            if a[i] > m {
                m = a[i];
            }
            i += 1;
        }

        // At this point, i == a.len(), so m is the max over all elements
        m
    }

}